def cjson(v):
    return json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(",",":"))

def logical_digest(db,table):
    cols=[r[1] for r in db.execute(f'PRAGMA table_info("{table}")')]
    h=hashlib.sha256()
    sel=", ".join(f'"{c}"' for c in cols)
    for row in db.execute(f'SELECT {sel} FROM "{table}" ORDER BY rowid'):
        h.update(cjson(list(row)).encode("utf-8"));h.update(b"\n")
    return h.hexdigest()

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--db",default=str(RULES_DB))
    ap.add_argument("--output",default=str(DEFAULT_OUTPUT))
    args=ap.parse_args()
    db=sqlite3.connect(args.db)
    errors=[]
    try:
        integrity=db.execute("PRAGMA integrity_check").fetchone()[0]
        fk=db.execute("PRAGMA foreign_key_check").fetchall()
        if integrity!="ok": errors.append(f"integrity={integrity}")
        if fk: errors.append(f"foreign_keys={len(fk)}")

        counts={
            "registry":db.execute("SELECT COUNT(*) FROM phase8_rule_registry").fetchone()[0],
            "structured_sections":db.execute("SELECT COUNT(*) FROM phase8_rule_registry WHERE disposition='STRUCTURED_RULE_CANDIDATE'").fetchone()[0],
            "review_sections":db.execute("SELECT COUNT(*) FROM phase8_rule_registry WHERE disposition='REVIEW_CONTEXT'").fetchone()[0],
            "links":db.execute("SELECT COUNT(*) FROM phase8_rule_family_links").fetchone()[0],
            "structured_links":db.execute("SELECT COUNT(*) FROM phase8_rule_family_links WHERE disposition='STRUCTURED_RULE_CANDIDATE'").fetchone()[0],
            "review_links":db.execute("SELECT COUNT(*) FROM phase8_rule_family_links WHERE disposition='REVIEW_CONTEXT'").fetchone()[0],
            "backlog":db.execute("SELECT COUNT(*) FROM phase8_automation_backlog").fetchone()[0],
            "batches":db.execute("SELECT COUNT(*) FROM phase8_baseline_batches").fetchone()[0],
        }
        expected={"registry":70,"structured_sections":60,"review_sections":10,"links":77,"structured_links":67,"review_links":10,"backlog":67,"batches":1}
        for k,v in expected.items():
            if counts[k]!=v: errors.append(f"{k} expected={v} actual={counts[k]}")

        reg_ids={r[0] for r in db.execute("SELECT section_id FROM phase8_rule_registry")}
        expected_ids={x["section_id"] for x in SECTION_MANIFEST}
        if reg_ids!=expected_ids:
            errors.append(f"registry_id_set mismatch missing={len(expected_ids-reg_ids)} extra={len(reg_ids-expected_ids)}")

        actual_links={(r[0],r[1],r[2]) for r in db.execute("SELECT section_id,family,disposition FROM phase8_rule_family_links")}
        expected_links={(x["section_id"],x["family"],x["disposition"]) for x in LINK_MANIFEST}
        if actual_links!=expected_links:
            errors.append(f"family_link_set mismatch missing={len(expected_links-actual_links)} extra={len(actual_links-expected_links)}")

        backlog_pairs={(r[0],r[1]) for r in db.execute("SELECT section_id,family FROM phase8_automation_backlog")}
        expected_backlog={(x["section_id"],x["family"]) for x in LINK_MANIFEST if x["disposition"]=="STRUCTURED_RULE_CANDIDATE"}
        if backlog_pairs!=expected_backlog:
            errors.append(f"backlog_set mismatch missing={len(expected_backlog-backlog_pairs)} extra={len(backlog_pairs-expected_backlog)}")

        bad_status=db.execute("""
            SELECT COUNT(*) FROM phase8_automation_backlog
            WHERE gap_type!='semantic_extraction' OR status!='PENDING_SEMANTIC_EXTRACTION'
        """).fetchone()[0]
        if bad_status: errors.append(f"bad_backlog_status={bad_status}")

        actual_family={r[0]:r[1] for r in db.execute("""
            SELECT family,COUNT(*) FROM phase8_rule_family_links
            WHERE disposition='STRUCTURED_RULE_CANDIDATE'
            GROUP BY family
        """)}
        if actual_family!=EXPECTED_FAMILY_COUNTS:
            errors.append("family_counts mismatch")

        malformed=0
        for (raw,) in db.execute("SELECT evidence_json FROM phase8_automation_backlog"):
            try: json.loads(raw)
            except Exception: malformed+=1
        if malformed: errors.append(f"malformed_json={malformed}")

        batch=db.execute("""
            SELECT registry_rows,structured_sections,review_sections,family_links,
                   structured_links,review_links,backlog_rows,
                   sources_digest,source_revisions_digest,sections_digest,entity_versions_digest,
                   phase_status,package_version
            FROM phase8_baseline_batches ORDER BY created_at DESC LIMIT 1
        """).fetchone()
        if not batch:
            errors.append("missing_batch")
        else:
            if tuple(batch[:7])!=(70,60,10,77,67,10,67):
                errors.append(f"batch_counts={tuple(batch[:7])}")
            current_digests=(
                logical_digest(db,"sources"),logical_digest(db,"source_revisions"),
                logical_digest(db,"sections"),logical_digest(db,"entity_versions")
            )
            if tuple(batch[7:11])!=current_digests:
                errors.append("source_digest_mismatch")
            if batch[11]!="STRUCTURED_BASELINE_APPLIED_PHASE8_OPEN":
                errors.append(f"bad_phase_status={batch[11]}")
            if batch[12]!="V4":
                errors.append(f"bad_package_version={batch[12]}")

        orphan_registry=db.execute("""
            SELECT COUNT(*) FROM phase8_rule_registry r
            LEFT JOIN sections s ON s.id=r.section_id
            WHERE s.id IS NULL
        """).fetchone()[0]
        orphan_links=db.execute("""
            SELECT COUNT(*) FROM phase8_rule_family_links l
            LEFT JOIN phase8_rule_registry r ON r.section_id=l.section_id
            WHERE r.section_id IS NULL
        """).fetchone()[0]
        if orphan_registry: errors.append(f"orphan_registry={orphan_registry}")
        if orphan_links: errors.append(f"orphan_links={orphan_links}")

        print(f"INTEGRITY={integrity}")
        print(f"FOREIGN_KEYS={len(fk)}")
        print(f"REGISTRY_ROWS={counts['registry']}")
        print(f"STRUCTURED_SECTIONS={counts['structured_sections']}")
        print(f"REVIEW_SECTIONS={counts['review_sections']}")
        print(f"FAMILY_LINKS={counts['links']}")
        print(f"STRUCTURED_LINKS={counts['structured_links']}")
        print(f"REVIEW_LINKS={counts['review_links']}")
        print(f"AUTOMATION_BACKLOG={counts['backlog']}")
        print(f"MALFORMED_JSON={malformed}")
        print(f"ORPHAN_REGISTRY={orphan_registry}")
        print(f"ORPHAN_LINKS={orphan_links}")
        print(f"ERRORS={len(errors)}")
        for e in errors: print("ERROR:",e)
        if errors: return 1
        print("PHASE_STATUS=STRUCTURED_BASELINE_APPLIED_PHASE8_OPEN")
        print("NEXT=PHASE8_FAMILY_SEMANTICS_AUDIT_V5")
        print("OK: Independent Phase 8 V4 verification")
        return 0
    finally:
        db.close()

if __name__=="__main__":
    raise SystemExit(main())
